 $('taskModalHeading').textContent=t?'Редактировать задачу':'Новая задача';$('formTitle').value=t?.title||'';
 const inferred=t?.planType||(!t?.date&&t?'inbox':t?'day':ui.route==='week'?'week':ui.route==='month'?'month':ui.route==='inbox'?'inbox':'day');
 $('formScope').value=inferred;
 $('formDate').value=t?.date||(ui.route==='inbox'?'':ui.anchor)||today();
 $('formEndDate').value=t?.endDate||t?.date||'';
 $('formTime').value=t?.time||'';$('formCategory').value=t?.category||'personal';$('formPriority').value=t?.priority||'normal';$('formRepeat').value=t?.repeat||'none';
 const [a,b]=t?timeEstimate(t):[0,0];$('formDurationMin').value=a||'';$('formDurationMax').value=b||'';
 $('formNote').value=t?.note||'';$('formSubtasks').value=t?.subtasks.map(x=>x.title).join('\n')||'';$('taskError').hidden=true;$('deleteTask').hidden=!t;
